package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {







    @Test
    public void testCreateNumber_Hexadecimal() throws NumberFormatException {
        // Testing 0x and -0x paths
        assertTrue(NumberUtils.createNumber("0x10") instanceof Integer);
        assertEquals(16, NumberUtils.createNumber("0x10").intValue());
        assertTrue(NumberUtils.createNumber("-0x10") instanceof Integer);
        assertEquals(-16, NumberUtils.createNumber("-0x10").intValue());
    }




















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {









    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        // Integer
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertEquals(123, NumberUtils.createNumber("123").intValue());

        // Long
        assertTrue(NumberUtils.createNumber("1234567890123") instanceof Long);
        assertEquals(1234567890123L, NumberUtils.createNumber("1234567890123").longValue());

        // BigInteger (Too large for long)
        String bigIntStr = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertTrue(NumberUtils.createNumber(bigIntStr) instanceof BigInteger);
    }


















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() throws NumberFormatException {
        // Float
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);
        assertEquals(1.23F, NumberUtils.createNumber("1.23f").floatValue(), 0.001);

        // Double
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);
        assertEquals(1.23D, NumberUtils.createNumber("1.23d").doubleValue(), 0.001);

        // BigDecimal
        assertTrue(NumberUtils.createNumber("1.234567890123456789") instanceof BigDecimal);
    }
















}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {













    @Test
    public void testCreateNumber_Suffixes() throws NumberFormatException {
        // Long suffix L
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);

        // BigInteger via Long suffix (overflow)
        String bigL = "9223372036854775808L";
        assertTrue(NumberUtils.createNumber(bigL) instanceof BigInteger);

        // Float suffix F
        assertTrue(NumberUtils.createNumber("1.23F") instanceof Float);

        // Double suffix D
        assertTrue(NumberUtils.createNumber("1.23D") instanceof Double);
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen4Test {















    @Test
    public void testCreateNumber_ScientificNotation() throws NumberFormatException {
        // No decimal, with exponent
        assertTrue(NumberUtils.createNumber("1e3") instanceof Integer || NumberUtils.createNumber("1e3") instanceof Long);

        // With decimal and exponent
        assertTrue(NumberUtils.createNumber("1.23e2") instanceof Float || NumberUtils.createNumber("1.23e2") instanceof Double);

        // Complex scientific with suffix
        assertTrue(NumberUtils.createNumber("1.23e2f") instanceof Float);
    }












}

