public class NumberUtils_createNumber_TriageGen4Test {

















    @Test
    public void testCreateNumber_EdgeCases() throws NumberFormatException {
        // Trailing dot
        assertTrue(NumberUtils.createNumber("123.") instanceof Double || NumberUtils.createNumber("123.") instanceof BigDecimal);

        // All zeros check (mantissa and exponent)
        // This triggers the logic: if (f.floatValue() == 0.0F && !allZeros)
        assertTrue(NumberUtils.createNumber("0.00e0") instanceof Float);
    }










}

